import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g2-3/bot.mjs';

const tokyo = (over = {}) => ({ id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3, ...over });
// Tokyo is UTC+9, no DST. Build a Date from a local Tokyo wall-clock time.
const at = (zone, offsetH, iso) => new Date(iso); // iso must include offset
let pass = 0;
const t = (name, fn) => { fn(); pass++; console.log('ok -', name); };

t('cap of 3 per local day, 4th blocked with daily_cap_reached', () => {
  const g = createPushGate();
  const u = tokyo();
  assert.deepEqual(g.attempt(u, new Date('2026-10-22T10:00:00+09:00')), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(u, new Date('2026-10-22T12:00:00+09:00')), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(u, new Date('2026-10-22T18:00:00+09:00')), { allowed: true, reason: null });
  assert.deepEqual(g.attempt(u, new Date('2026-10-22T20:00:00+09:00')), { allowed: false, reason: 'daily_cap_reached' });
});

t('new local day resets the cap', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 1 });
  assert.equal(g.attempt(u, new Date('2026-10-22T10:00:00+09:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-10-22T11:00:00+09:00')).reason, 'daily_cap_reached');
  assert.equal(g.attempt(u, new Date('2026-10-23T00:01:00+09:00')).allowed, true);
});

t('day is the user zone, not UTC: 23:30 NY and 00:30 NY next day are different days', () => {
  const g = createPushGate();
  const u = { id: 'ny', timeZone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  // 2026-10-22 23:30 EDT (UTC-4) = 2026-10-23 03:30Z: same UTC day as the next push, different NY day.
  assert.equal(g.attempt(u, new Date('2026-10-22T23:30:00-04:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-10-23T00:30:00-04:00')).allowed, true);
});

t('same UTC day but different local days in a far zone are counted per local day', () => {
  const g = createPushGate();
  const u = { id: 'la', timeZone: 'America/Los_Angeles', quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  // 2026-10-22 17:00 PDT (UTC-7) = 2026-10-23 00:00Z
  assert.equal(g.attempt(u, new Date('2026-10-22T17:00:00-07:00')).allowed, true);
  // 2026-10-22 20:00 PDT = 2026-10-23 03:00Z -> same local day, blocked
  assert.equal(g.attempt(u, new Date('2026-10-22T20:00:00-07:00')).reason, 'daily_cap_reached');
});

t('quiet hours wrap past midnight: 22:00-07:00 blocks, 07:00 allowed', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 10 });
  assert.equal(g.attempt(u, new Date('2026-10-22T22:00:00+09:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-23T00:30:00+09:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-23T06:59:00+09:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-23T07:00:00+09:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-10-23T21:59:00+09:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-10-23T22:00:00+09:00')).reason, 'quiet_hours');
});

t('quiet hours are in the user zone, not the server zone', () => {
  const g = createPushGate();
  // 2026-10-22 23:00 UTC is 08:00 Tokyo next day -> allowed in Tokyo
  const u = tokyo();
  assert.equal(g.attempt(u, new Date('2026-10-22T23:00:00Z')).allowed, true);
  // 2026-10-22 23:00 in Tokyo is 14:00 UTC -> blocked
  assert.equal(g.attempt(tokyo({ id: 'other' }), new Date('2026-10-22T14:00:00Z')).allowed, true);
  assert.equal(g.attempt(tokyo({ id: 'x' }), new Date('2026-10-22T14:00:00Z')).allowed, true);
  assert.equal(g.attempt(tokyo({ id: 'y' }), new Date('2026-10-22T13:30:00Z')).allowed, true);
  assert.equal(g.attempt(tokyo({ id: 'z' }), new Date('2026-10-22T14:30:00Z')).reason, 'quiet_hours');
});

t('non-wrapping quiet period 13:00-14:00', () => {
  const g = createPushGate();
  const u = { id: 'nw', timeZone: 'UTC', quietStart: '13:00', quietEnd: '14:00', dailyCap: 5 };
  assert.equal(g.attempt(u, new Date('2026-10-22T12:59:00Z')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-10-22T13:00:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-22T13:59:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-22T14:00:00Z')).allowed, true);
});

t('start === end disables quiet hours; missing bounds too', () => {
  const g = createPushGate();
  assert.equal(g.attempt({ id: 'a', timeZone: 'UTC', quietStart: '08:00', quietEnd: '08:00', dailyCap: 5 }, new Date('2026-10-22T08:30:00Z')).allowed, true);
  assert.equal(g.attempt({ id: 'b', timeZone: 'UTC', quietStart: null, quietEnd: undefined, dailyCap: 5 }, new Date('2026-10-22T03:00:00Z')).allowed, true);
});

t('quiet block does not consume the daily cap', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 1 });
  assert.equal(g.attempt(u, new Date('2026-10-22T23:00:00+09:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, new Date('2026-10-23T08:00:00+09:00')).allowed, true);
});

t('cap 0 blocks everything with daily_cap_reached', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo({ dailyCap: 0 }), new Date('2026-10-22T10:00:00+09:00')).reason, 'daily_cap_reached');
});

t('quiet check runs before cap check', () => {
  const g = createPushGate();
  const u = tokyo({ dailyCap: 0 });
  assert.equal(g.attempt(u, new Date('2026-10-22T23:00:00+09:00')).reason, 'quiet_hours');
});

t('users are isolated; each gate has its own history', () => {
  const g1 = createPushGate();
  const g2 = createPushGate();
  const a = tokyo({ id: 'a', dailyCap: 1 });
  const b = tokyo({ id: 'b', dailyCap: 1 });
  const now = new Date('2026-10-22T10:00:00+09:00');
  assert.equal(g1.attempt(a, now).allowed, true);
  assert.equal(g1.attempt(a, now).reason, 'daily_cap_reached');
  assert.equal(g1.attempt(b, now).allowed, true);
  assert.equal(g2.attempt(a, now).allowed, true);
});

t('settings are read per call (cap lowered mid-day takes effect)', () => {
  const g = createPushGate();
  const now = (h) => new Date(`2026-10-22T${h}:00+09:00`);
  assert.equal(g.attempt(tokyo({ dailyCap: 5 }), now('10')).allowed, true);
  assert.equal(g.attempt(tokyo({ dailyCap: 1 }), now('11')).reason, 'daily_cap_reached');
});

t('DST zone: Europe/Berlin spring-forward day counted correctly', () => {
  const g = createPushGate();
  const u = { id: 'de', timeZone: 'Europe/Berlin', quietStart: '00:00', quietEnd: '00:00', dailyCap: 2 };
  // 2026-03-29 is the spring-forward day in Europe (02:00 -> 03:00 CET->CEST)
  assert.equal(g.attempt(u, new Date('2026-03-29T00:30:00+01:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-03-29T12:00:00+02:00')).allowed, true);
  assert.equal(g.attempt(u, new Date('2026-03-29T23:00:00+02:00')).reason, 'daily_cap_reached');
  assert.equal(g.attempt(u, new Date('2026-03-30T00:10:00+02:00')).allowed, true);
});

t('invalid inputs throw', () => {
  const g = createPushGate();
  const now = new Date('2026-10-22T10:00:00Z');
  assert.throws(() => g.attempt(tokyo({ quietStart: '25:00' }), now), TypeError);
  assert.throws(() => g.attempt(tokyo({ quietEnd: '7:00' }), now), TypeError);
  assert.throws(() => g.attempt(tokyo({ dailyCap: -1 }), now), TypeError);
  assert.throws(() => g.attempt(tokyo({ dailyCap: 2.5 }), now), TypeError);
  assert.throws(() => g.attempt(tokyo({ dailyCap: '3' }), now), TypeError);
  assert.throws(() => g.attempt(tokyo(), new Date('nope')), TypeError);
  assert.throws(() => g.attempt(tokyo(), '2026-10-22'), TypeError);
  assert.throws(() => g.attempt(tokyo({ timeZone: 'Mars/Olympus' }), now), RangeError);
});

t('returned object shape: only allowed and reason; reason null when allowed', () => {
  const g = createPushGate();
  const r = g.attempt(tokyo({ dailyCap: 1 }), new Date('2026-10-22T10:00:00+09:00'));
  assert.deepEqual(Object.keys(r).sort(), ['allowed', 'reason']);
  assert.equal(r.reason, null);
  assert.deepEqual(Object.keys(createPushGate()).sort(), ['attempt']);
});

t('performance: 100k calls stay fast', () => {
  const g = createPushGate();
  const start = Date.now();
  for (let i = 0; i < 100000; i++) {
    g.attempt({ id: 'u' + (i % 1000), timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 },
      new Date(Date.UTC(2026, 9, 22, 1) + i * 1000));
  }
  console.log('   100k calls in', Date.now() - start, 'ms');
});

console.log(`\n${pass} groups passed`);
